SEED='demo'
W="await T.w(450);"
CASES=[
 ('TSK-01','Tasks','Create a task with description, due date/time and priority',"(async()=>{showTab('pgTasks');openTask(null);"+W+"T.set('#taskTitleIn','QA Task');T.set('#taskDescIn','details here');T.set('#taskDueDateIn',today());T.set('#taskDueTimeIn','18:30');const p=T.q('#taskPriorityRow [data-tp=high]');if(p)p.click();T.click('#taskSave');"+W+"const t=state.tasks.find(t=>t.title==='QA Task');return T.ok(t&&t.description==='details here'&&t.dueDate===today()&&t.dueTime==='18:30'&&t.priority==='high',t&&[t.dueDate,t.dueTime,t.priority])})()"),
 ('TSK-02','Tasks','Empty title is rejected',"(async()=>{const n=state.tasks.length;openTask(null);"+W+"T.set('#taskTitleIn','  ');T.click('#taskSave');"+W+"const ok=state.tasks.length===n;closeSheet();return T.ok(ok,n+'->'+state.tasks.length)})()"),
 ('TSK-03','Tasks','Add subtasks and a comment',"(async()=>{const t=state.tasks.find(t=>t.title==='QA Task');openTask(t.id);"+W+"T.set('#taskSubInput','step one');T.click('#taskSubAdd');await T.w(200);T.set('#taskSubInput','step two');T.click('#taskSubAdd');await T.w(200);T.set('#taskCommentInput','note to self');T.click('#taskCommentAdd');await T.w(200);T.click('#taskSave');"+W+"const x=state.tasks.find(x=>x.id===t.id);return T.ok((x.subtasks||[]).length===2&&(x.comments||[]).length>=1,'subtasks '+(x.subtasks||[]).length+' comments '+(x.comments||[]).length)})()"),
 ('TSK-04','Tasks','Complete a task, then reopen it',"(()=>{const t=state.tasks.find(t=>t.title==='QA Task');toggleTaskComplete(t.id);const a=t.status;toggleTaskComplete(t.id);return T.ok(a==='completed'&&t.status!=='completed',a+' -> '+t.status)})()"),
 ('TSK-05','Tasks','A task due yesterday shows as overdue',"(async()=>{openTask(null);"+W+"const y=new Date();y.setDate(y.getDate()-1);T.set('#taskTitleIn','QA Late');T.set('#taskDueDateIn',fmt(y));T.click('#taskSave');"+W+"const t=state.tasks.find(t=>t.title==='QA Late');return T.ok(taskEffectiveStatus(t)==='overdue',taskEffectiveStatus(t))})()"),
 ('TSK-06','Tasks','Count tiles match the filtered lists',"(async()=>{showTab('pgTasks');await T.w(300);const r={};for(const [cls,f] of [['over','overdue'],['today','today'],['up','upcoming']]){const n=+T.q('#taskSummary .tscv.'+cls+' b').textContent;taskFilter=f;renderTasks();await T.w(150);r[f]=[n,T.qa('#taskList .taskCard').length];}taskFilter='all';renderTasks();return T.ok(Object.values(r).every(([a,b])=>a===b),r)})()"),
 ('TSK-07','Tasks','Tapping a count tile filters the list',"(async()=>{showTab('pgTasks');await T.w(300);T.click('#taskSummary .tscv.over');await T.w(300);const f=T.q('#taskFilters .sel').getAttribute('data-tf');T.click('#taskFilters [data-tf=all]');return T.ok(f==='overdue',f)})()"),
 ('TSK-08','Tasks','Search finds tasks by description and subtask text',"(async()=>{showTab('pgTasks');T.set('#taskSearch','step two');await T.w(500);const a=T.qa('#taskList .taskCard').length;T.set('#taskSearch','details here');await T.w(500);const b=T.qa('#taskList .taskCard').length;T.set('#taskSearch','');await T.w(400);return T.ok(a>=1&&b>=1,'subtask hit '+a+' desc hit '+b)})()"),
 ('TSK-09','Tasks','Menu: Pin, Snooze to tomorrow and Duplicate work',"(async()=>{showTab('pgTasks');await T.w(300);const t=state.tasks.find(t=>t.title==='QA Late');const card=()=>T.q('#taskList .taskCard[data-task-id=\"'+t.id+'\"]');card().querySelector('.tcMore').click();await T.w(250);card().querySelector('[data-task-pin]').click();await T.w(350);const pinned=t.pinned;card().querySelector('.tcMore').click();await T.w(250);card().querySelector('[data-task-snooze]').click();await T.w(350);const tm=new Date();tm.setDate(tm.getDate()+1);const snoozed=state.tasks.find(x=>x.id===t.id).dueDate===fmt(tm);const n=state.tasks.length;card().querySelector('.tcMore').click();await T.w(250);card().querySelector('[data-task-dup]').click();await T.w(350);return T.ok(pinned&&snoozed&&state.tasks.length===n+1,'pinned '+pinned+' snoozed '+snoozed+' duplicated '+(state.tasks.length===n+1))})()"),
 ('TSK-10','Tasks','Delete moves the task to Recently deleted; restore works',"(async()=>{const t=state.tasks.find(t=>t.title==='QA Late');openTask(t.id);"+W+"window.confirm=()=>true;const d=T.q('#taskDelete');d.click();"+W+"if(state.tasks.some(x=>x.id===t.id)){d.click();"+W+"}const ix=(state.trash||[]).findIndex(x=>x.item&&x.item.id===t.id);if(ix>=0)restoreFromTrash(ix);return T.ok(ix>=0&&state.tasks.some(x=>x.id===t.id),'trash '+(ix>=0))})()"),
 ('TSK-11','Tasks','Code in a task title is shown as text, never run',"(async()=>{window.__xss=0;openTask(null);"+W+"T.set('#taskTitleIn','<img src=x onerror=\"window.__xss=1\">T');T.click('#taskSave');"+W+"showTab('pgTasks');await T.w(500);return T.ok(window.__xss===0&&!T.q('#taskList img[src=\"x\"]'),'executed '+window.__xss)})()"),
 ('TSK-12','Tasks','Export opens and produces a file',"(async()=>{showTab('pgTasks');window.__saved=[];const os=window.webSave;window.webSave=function(n){__saved.push(n);return true};T.click('#taskExportToggle');await T.w(500);const open=sheetOpen==='taskExportSheet';const x=T.qa('#taskExportSheet button').find(b=>/excel/i.test(b.textContent));if(x)x.click();await T.w(1500);window.webSave=os;return T.ok(open&&__saved.length>0,'sheet '+open+' files '+__saved)})()"),
 ('TSK-13','Tasks','Double-tap Save creates the task only once',"(async()=>{openTask(null);"+W+"T.set('#taskTitleIn','QA Double');const b=T.q('#taskSave');b.click();b.click();"+W+"return T.ok(state.tasks.filter(t=>t.title==='QA Double').length===1,state.tasks.filter(t=>t.title==='QA Double').length)})()"),
 ('TSK-14','Tasks','Tasks survive a reload',"RELOAD:(()=>{const t=state.tasks.find(t=>t.title==='QA Task');return T.ok(t&&(t.subtasks||[]).length===2,'ok')})()"),
]
